class Shape {
    protected String name;
    public Shape(String name) { this.name = name; }
    public double calculateArea() { return 0.0; }
    public void describe() {
        System.out.println(name + " -> Area: " + String.format("%.2f", calculateArea()));
    }
}

class Circle extends Shape {
    private double radius;
    public Circle(double radius) {
        super("Circle");
        this.radius = radius;
    }
    @Override
    public double calculateArea() {
        return Math.PI * radius * radius;
    }
}

class Rectangle extends Shape {
    private double width, height;
    public Rectangle(double width, double height) {
        super("Rectangle");
        this.width = width;
        this.height = height;
    }
    @Override
    public double calculateArea() {
        return width * height;
    }
}

public class ShapeBatchDemo {
    public static void main(String[] args) {
        Shape[] drawing = new Shape[] {
            new Circle(3.0),
            new Rectangle(4.0, 5.0),
            new Circle(1.5)
        };

        double totalArea = 0.0;
        for (Shape s : drawing) {
            s.describe();
            totalArea += s.calculateArea();
        }
        System.out.println("Total Canvas Area: " + String.format("%.2f", totalArea));
    }
}

