class Notification {
    public void send(String recipient, String message) {
        System.out.println("[Default] To: " + recipient + " | " + message);
    }
}

class EmailNotification extends Notification {
    @Override
    public void send(String recipient, String message) {
        System.out.println("[Email Server] Connecting SMTP... Sending to " + recipient + ": " + message);
    }
}

class SMSNotification extends Notification {
    @Override
    public void send(String recipient, String message) {
        System.out.println("[SMS Gateway] Dispatching telecom packet to " + recipient + ": " + message);
    }
}

class NotificationDispatcher {
    // Method accepts the generic parent type!
    public static void broadcast(Notification channel, String user, String alert) {
        channel.send(user, alert);
    }
}

public class NotificationDemo {
    public static void main(String[] args) {
        Notification email = new EmailNotification();
        Notification sms = new SMSNotification();

        NotificationDispatcher.broadcast(email, "alice@corp.com", "Server CPU load 92%");
        NotificationDispatcher.broadcast(sms, "+1555019283", "Urgent: Database failover");
    }
}

