        super(model);
    }
    @Override
    public void move() {
        System.out.println(model + " drives on road at 60 mph");
    }
}

class Bicycle extends Vehicle {
    public Bicycle(String model) {
        super(model);
    }
    @Override
    public void move() {
        System.out.println(model + " pedals on bike lane at 15 mph");
    }
}

public class FleetApp {
    public static void main(String[] args) {
        Vehicle[] fleet = new Vehicle[] {
            new Car("Tesla"),
            new Bicycle("Trek")
        };
        for (Vehicle v : fleet) {
            v.move();
        }
    }
}

class TaxPayer {
    protected String name;
    protected double grossIncome;
    public TaxPayer(String name, double grossIncome) {
        this.name = name;
        this.grossIncome = grossIncome;
    }
    public double calculateTax() {
        return grossIncome * 0.15;
    }
    public String getName() { return name; }
}

class SalariedEmployee extends TaxPayer {
    public SalariedEmployee(String name, double grossIncome) {
        super(name, grossIncome);
    }
    @Override
    public double calculateTax() {
        if (grossIncome <= 50000.0) {
            return grossIncome * 0.10;
        } else {
            return (50000.0 * 0.10) + ((grossIncome - 50000.0) * 0.20);
        }
    }
}

class Contractor extends TaxPayer {
    public Contractor(String name, double grossIncome) {
        super(name, grossIncome);
    }
    @Override
    public double calculateTax() {
        return grossIncome * 0.12;
    }
}

public class TaxEngineApp {
    public static void main(String[] args) {
        TaxPayer[] payers = new TaxPayer[] {
            new SalariedEmployee("Alice", 70000.0),
            new Contractor("Bob", 40000.0),
            new TaxPayer("Charlie", 30000.0)
        };
        for (TaxPayer tp : payers) {
            System.out.println(tp.getName() + ": $" + String.format("%.1f", tp.calculateTax()));
        }
    }
}

class AudioFilter {
    public String process(String sample) {
        return "[Raw] " + sample;
    }
}

class EchoFilter extends AudioFilter {
    @Override
    public String process(String sample) {
        return "[Echo: " + sample + " ... " + sample + "]";
    }
}

class ReverbFilter extends AudioFilter {
    @Override
    public String process(String sample) {
        return "[Reverb: ~" + sample + "~]";
    }
}

class NoiseGateFilter extends AudioFilter {
    @Override
    public String process(String sample) {
        return "[Gated: " + sample + "]";
    }
}

public class AudioProcessorApp {
    public static void main(String[] args) {
        AudioFilter[] chain = new AudioFilter[] {
            new EchoFilter(),
            new ReverbFilter(),
            new NoiseGateFilter()
        };
        String sample = "Vocals_Take1";
        for (AudioFilter filter : chain) {
            System.out.println(filter.process(sample));
        }
    }
}

