class SqlDialect {
    public String paginate(String query, int offset, int limit) {
        return query + " FETCH FIRST " + limit + " ROWS ONLY";
    }
}

class MySqlDialect extends SqlDialect {
    @Override
    public String paginate(String query, int offset, int limit) {
        return query + " LIMIT " + offset + ", " + limit;
    }
}

class PostgresDialect extends SqlDialect {
    @Override
    public String paginate(String query, int offset, int limit) {
        return query + " LIMIT " + limit + " OFFSET " + offset;
    }
}

class OracleDialect extends SqlDialect {
    @Override
    public String paginate(String query, int offset, int limit) {
        return "SELECT * FROM (" + query + ") WHERE ROWNUM <= " + limit;
    }
}

public class SqlDialectApp {
    public static void main(String[] args) {
        SqlDialect[] dialects = new SqlDialect[] {
            new MySqlDialect(),
            new PostgresDialect(),
            new OracleDialect()
        };
        String baseQuery = "SELECT * FROM users";
        for (SqlDialect dialect : dialects) {
            System.out.println(dialect.paginate(baseQuery, 10, 5));
        }
    }
}
